// Booking status panel «Что дальше»: three steps after the patient sends the booking —
// accepted, confirmation to their contact, appointment at the chosen time (catalog D49 flow).
// Live state change via motion/react, respects reduced motion. Composition follows the
// pattern of the library cta-band, rewritten on the design system tokens.
import { domAnimation, LazyMotion, m } from 'motion/react';
import { useReducedMotion } from 'react';

type Step = { title: string; text: string };

export type BookingStatusStepsProps = {
  title: string;
  intro?: string;
  steps: Step[];
  currentStep: number;
  note?: string;
};

export default function BookingStatusSteps({ title, intro, steps, currentStep, note }: BookingStatusStepsProps) {
  const reduce = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="mx-auto max-w-text min-w-0">
          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
          {intro ? <p className="mt-3 text-lead text-muted-foreground">{intro}</p> : null}
        </div>

        <LazyMotion features={domAnimation}>
          <ol className="mt-10 grid gap-4 md:grid-cols-3 md:gap-6">
            {steps.map((step, i) => {
              const number = i + 1;
              const active = currentStep === number;
              const done = currentStep > number;
              return (
                <li
                  key={step.title}
                  className="min-w-0 rounded-lg border bg-card p-6"
                  style={
                    active
                      ? { borderColor: 'var(--color-primary)' }
                      : done
                        ? { borderColor: 'var(--color-primary)' }
                        : undefined
                  }
                >
                  <div className="flex items-center gap-4">
                    <span
                      aria-hidden="true"
                      className={
                        active || done
                          ? 'inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary font-display text-h3 font-bold text-primary-foreground'
                          : 'inline-flex min-h-11 min-w-11 items-center justify-center rounded-control border bg-background font-display text-h3 font-bold text-muted-foreground'
                      }
                    >
                      {done ? '✓' : number}
                    </span>
                    <span className="min-w-0 text-small font-bold uppercase tracking-wide text-muted-foreground">
                      {done ? (reduce ? '' : 'выполнено') : active ? 'сейчас' : `шаг ${number}`}
                    </span>
                  </div>
                  <h3 className="mt-4 font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                  <p className="mt-2 text-body text-muted-foreground wrap-break-word">{step.text}</p>
                  {active ? (
                    <m.div
                      className="mt-4 h-1 rounded-sm bg-primary"
                      initial={reduce ? false : { scaleX: 0 }}
                      animate={{ scaleX: 1 }}
                      transition={{ duration: reduce ? 0 : 0.6, ease: 'easeOut' }}
                      style={{ transformOrigin: 'left' }}
                    />
                  ) : (
                    <div className="mt-4 h-1 rounded-sm bg-border" aria-hidden="true" />
                  )}
                </li>
              );
            })}
          </ol>
        </LazyMotion>

        {note ? <p className="mt-8 max-w-text text-small text-muted-foreground wrap-break-word">{note}</p> : null}
      </div>
    </section>
  );
}

// Booking status panel «Что дальше»: after the patient sends the booking, a two-part panel shows
// the current state on the left and a vertical timeline of steps on the right — accepted,
// confirmation to their contact, appointment at the chosen time (catalog D49 flow).
// Live state change via motion/react, respects reduced motion.
import { domAnimation, LazyMotion, m } from 'motion/react';
import { useReducedMotion } from 'react';

type Step = { title: string; text: string };

export type BookingStatusStepsProps = {
  title: string;
  intro?: string;
  statusLabel: string;
  steps: Step[];
  currentStep: number;
  note?: string;
};

export default function BookingStatusSteps({ title, intro, statusLabel, steps, currentStep, note }: BookingStatusStepsProps) {
  const reduce = useReducedMotion();
  const progress = steps.length > 0 ? Math.min(Math.max(currentStep, 0), steps.length) / steps.length : 0;

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid min-w-0 gap-8 rounded-lg border bg-card p-6 md:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)] md:gap-12 md:p-10">
          <div className="flex min-w-0 flex-col">
            <div className="flex flex-wrap items-center gap-3">
              <span className="inline-flex min-h-11 items-center rounded-control bg-primary px-4 text-small font-bold text-primary-foreground">
                {statusLabel}
              </span>
            </div>
            <h2 className="mt-4 font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
            {intro ? <p className="mt-3 text-lead text-muted-foreground wrap-break-word">{intro}</p> : null}
            <div className="mt-auto pt-6" aria-hidden="true">
              <LazyMotion features={domAnimation}>
                <div className="h-1 w-full overflow-hidden rounded-sm bg-border">
                  <m.div
                    className="h-full bg-primary"
                    initial={reduce ? false : { width: 0 }}
                    animate={{ width: `${Math.round(progress * 100)}%` }}
                    transition={{ duration: reduce ? 0 : 0.6, ease: 'easeOut' }}
                  />
                </div>
              </LazyMotion>
            </div>
          </div>

          <ol className="relative flex min-w-0 flex-col gap-8 border-t pt-8 md:border-l md:border-t-0 md:pl-10 md:pt-0">
            {steps.map((step, i) => {
              const number = i + 1;
              const active = currentStep === number;
              const done = currentStep > number;
              const label = done ? 'выполнено' : active ? 'сейчас' : `шаг ${number}`;
              return (
                <li key={step.title} className="flex min-w-0 gap-4">
                  <span
                    aria-hidden="true"
                    className={
                      active || done
                        ? 'inline-flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-control bg-primary font-display text-h3 font-bold text-primary-foreground'
                        : 'inline-flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-control border bg-background font-display text-h3 font-bold text-muted-foreground'
                    }
                  >
                    {done ? '✓' : number}
                  </span>
                  <div className="min-w-0">
                    <p className="text-small font-bold uppercase tracking-wide text-muted-foreground">{label}</p>
                    <h3 className="mt-1 font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                    <p className="mt-1 text-body text-muted-foreground wrap-break-word">{step.text}</p>
                  </div>
                </li>
              );
            })}
          </ol>
        </div>

        {note ? <p className="mt-6 max-w-text text-small text-muted-foreground wrap-break-word">{note}</p> : null}
      </div>
    </section>
  );
}

// Booking status panel «Что дальше»: after the patient sends the booking, a two-part panel shows
// the current state on the left and a vertical timeline of steps on the right — accepted,
// confirmation to their contact, appointment at the chosen time (catalog D49 flow).
// Live state change via motion/react, respects reduced motion.
import { domAnimation, LazyMotion, m, useReducedMotion } from 'motion/react';

type Step = { title: string; text: string };

export type BookingStatusStepsProps = {
  title: string;
  intro?: string;
  statusLabel: string;
  steps: Step[];
  currentStep: string;
  note?: string;
};

export default function BookingStatusSteps({ title, intro, statusLabel, steps, currentStep, note }: BookingStatusStepsProps) {
  const reduce = useReducedMotion();
  const step = Math.round(Number(currentStep) || 0);
  const progress = steps.length > 0 ? Math.min(Math.max(step, 0), steps.length) / steps.length : 0;

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid min-w-0 gap-8 rounded-lg border bg-card p-6 md:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)] md:gap-12 md:p-10">
          <div className="flex min-w-0 flex-col">
            <div className="flex flex-wrap items-center gap-3">
              <span className="inline-flex min-h-11 items-center rounded-control bg-primary px-4 text-small font-bold text-primary-foreground">
                {statusLabel}
              </span>
            </div>
            <h2 className="mt-4 font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
            {intro ? <p className="mt-3 text-lead text-muted-foreground wrap-break-word">{intro}</p> : null}
            <div className="mt-auto pt-6" aria-hidden="true">
              <LazyMotion features={domAnimation}>
                <div className="h-1 w-full overflow-hidden rounded-sm bg-border">
                  <m.div
                    className="h-full bg-primary"
                    initial={reduce ? false : { width: 0 }}
                    animate={{ width: `${Math.round(progress * 100)}%` }}
                    transition={{ duration: reduce ? 0 : 0.6, ease: 'easeOut' }}
                  />
                </div>
              </LazyMotion>
            </div>
          </div>

          <ol className="relative flex min-w-0 flex-col gap-8 border-t pt-8 md:border-l md:border-t-0 md:pl-10 md:pt-0">
            {steps.map((s, i) => {
              const number = i + 1;
              const active = step === number;
              const done = step > number;
              const label = done ? 'выполнено' : active ? 'сейчас' : `шаг ${number}`;
              return (
                <li key={s.title} className="flex min-w-0 gap-4">
                  <span
                    aria-hidden="true"
                    className={
                      active || done
                        ? 'inline-flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-control bg-primary font-display text-h3 font-bold text-primary-foreground'
                        : 'inline-flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-control border bg-background font-display text-h3 font-bold text-muted-foreground'
                    }
                  >
                    {done ? '✓' : number}
                  </span>
                  <div className="min-w-0">
                    <p className="text-small font-bold uppercase tracking-wide text-muted-foreground">{label}</p>
                    <h3 className="mt-1 font-display text-h3 font-bold text-balance wrap-break-word">{s.title}</h3>
                    <p className="mt-1 text-body text-muted-foreground wrap-break-word">{s.text}</p>
                  </div>
                </li>
              );
            })}
          </ol>
        </div>

        {note ? <p className="mt-6 max-w-text text-small text-muted-foreground wrap-break-word">{note}</p> : null}
      </div>
    </section>
  );
}

