// «Как проходит онлайн-запись»: тонкая полоса-таймлайн под формой — три точки с крупными цифрами,
// соединённые линией; на телефонах карточки складываются в столбец, линия идёт слева.
type Step = { caption: string; description: string };

export type TimelineBookingStepsProps = {
  title: string;
  steps: [Step, Step, Step] | Step[];
  hint?: string;
};

import { LazyMotion, m, domAnimation, useReducedMotion } from 'motion/react';

export default function TimelineBookingSteps({ title, steps, hint }: TimelineBookingStepsProps) {
  const reduce = useReducedMotion();
  const animate = !reduce;

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
        {hint ? <p className="mt-2 max-w-text text-lead text-muted-foreground wrap-break-word">{hint}</p> : null}

        <LazyMotion features={domAnimation}>
          <ol className="relative mt-10 grid list-none gap-8 md:grid-cols-3 md:gap-6">
            {steps.slice(0, 3).map((step, i) => (
              <li
                key={step.caption}
                className="relative flex min-w-0 items-start gap-4 md:flex-col md:items-stretch"
              >
                <m.div
                  initial={animate ? { opacity: 0, y: 16 } : undefined}
                  whileInView={animate ? { opacity: 1, y: 0 } : undefined}
                  viewport={{ once: true }}
                  transition={{ duration: 0.35, delay: i * 0.12 }}
                  className="flex min-w-0 flex-1 items-start gap-4 md:block"
                >
                  <span
                    aria-hidden="true"
                    className="flex size-14 shrink-0 items-center justify-center rounded-lg border border-border bg-card font-display text-h2 font-bold text-primary"
                  >
                    {i + 1}
                  </span>
                  <div className="min-w-0 md:mt-4">
                    <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.caption}</h3>
                    <p className="mt-2 text-body text-muted-foreground wrap-break-word">{step.description}</p>
                  </div>
                </m.div>

                {i < Math.min(steps.length, 3) - 1 ? (
                  <span
                    aria-hidden="true"
                    className="absolute top-7 h-0.5 w-[calc(100%-3.5rem)] border-t-2 border-dashed border-border md:top-7 md:left-14 md:w-auto md:[transform:none]"
                  />
                ) : null}
              </li>
            ))}
          </ol>
        </LazyMotion>
      </div>
    </section>
  );
}

// «Как проходит онлайн-запись»: тонкая полоса-таймлайн — точки с крупными цифрами на общей
// линии, подписи под точками; на телефонах линия идёт вертикально слева. Это полоса-схема,
// а не ряд карточек: одна композиция с общей осью.
type Step = { caption: string; description: string };

export type TimelineBookingStepsProps = {
  title: string;
  steps: Step[];
  hint?: string;
};

import { LazyMotion, m, domAnimation, useReducedMotion } from 'motion/react';

export default function TimelineBookingSteps({ title, steps, hint }: TimelineBookingStepsProps) {
  const reduce = useReducedMotion();
  const animate = !reduce;
  const list = steps.slice(0, 3);

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
        {hint ? <p className="mt-2 max-w-text text-lead text-muted-foreground wrap-break-word">{hint}</p> : null}

        <LazyMotion features={domAnimation}>
          <ol className="relative mt-12 list-none md:mt-14">
            {list.map((step, i) => (
              <m.li
                key={step.caption}
                initial={animate ? { opacity: 0, x: -12 } : undefined}
                whileInView={animate ? { opacity: 1, x: 0 } : undefined}
                viewport={{ once: true }}
                transition={{ duration: 0.35, delay: i * 0.15 }}
                className="relative flex min-w-0 items-start gap-5 pb-10 last:pb-0 md:items-center md:gap-0"
              >
                {i < list.length - 1 ? (
                  <span
                    aria-hidden="true"
                    className="absolute top-14 bottom-0 w-0.5 bg-border md:top-auto md:left-7 md:h-0.5 md:w-[calc(33.333%-2rem)] md:translate-x-14 md:translate-y-0"
                  />
                ) : null}

                <span
                  aria-hidden="true"
                  className="relative z-10 flex size-14 shrink-0 items-center justify-center rounded-full border-2 border-primary bg-card font-display text-h3 font-bold text-primary md:size-16"
                >
                  {i + 1}
                </span>

                <div className="min-w-0 flex-1 md:max-w-[33.333%] md:pl-6">
                  <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.caption}</h3>
                  <p className="mt-1 text-body text-muted-foreground wrap-break-word">{step.description}</p>
                </div>
              </m.li>
            ))}
          </ol>
        </LazyMotion>
      </div>
    </section>
  );
}
